/**
 * Local Growth Engine — database schema (single source of truth).
 *
 * Design decisions (see README for the full rationale):
 * - Drizzle ORM + PostgreSQL, migrations generated by drizzle-kit.
 * - All IDs are UUID v4 (gen_random_uuid()), snake_case columns, timestamptz.
 * - Enums are enforced with real Postgres ENUM types (pgEnum) — consistent for
 *   every lifecycle/status column, extended by ALTER TYPE in later migrations.
 * - Scores use CHECK constraints (0–100) as a second line of defense beyond the
 *   scoring engines that will be built in later briefs.
 * - One JSONB `provenance` column carries per-field source metadata instead of
 *   one column per field (per master spec).
 * - `metrics.dimension` is jsonb with a unique index over (dimension::text) —
 *   jsonb has no btree opclass in Postgres, and jsonb text output is canonical,
 *   so equality on the text form gives the required uniqueness semantics.
 * - Money is stored as integer minor units (cents) — never floats.
 * - NO raw card or payment data anywhere by design.
 * - `tasks`, `exceptions`, and `audit_logs` use generic entity_type/entity_id
 *   so they can reference any table without fabricating FKs.
 */

import { sql } from 'drizzle-orm';
import {
  boolean,
  check,
  date,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  text,
  timestamp,
  unique,
  uuid,
} from 'drizzle-orm/pg-core';

