export const contacts = pgTable(
  'contacts',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    business_id: uuid('business_id')
      .notNull()
      .references(() => businesses.id, { onDelete: 'cascade' }),
    name: text('name').notNull(),
    role: text('role'),
    email: text('email'),
    phone: text('phone'),
    source: text('source'),
    verified_at: timestamp('verified_at', { withTimezone: true }),
    contactability_score: integer('contactability_score'),
    status: contactStatus('status').default('ACTIVE').notNull(),
    created_at: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updated_at: timestamp('updated_at', { withTimezone: true })
      .defaultNow()
      .notNull()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    index('idx_contacts_business_id').on(t.business_id),
    index('idx_contacts_email').on(t.email),
    index('idx_contacts_status').on(t.status),
    check('chk_contacts_contactability', sql`${t.contactability_score} BETWEEN 0 AND 100 OR ${t.contactability_score} IS NULL`),
  ],
);

