export const websiteAnalyses = pgTable(
  'website_analyses',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    website_id: uuid('website_id')
      .notNull()
      .references(() => websites.id, { onDelete: 'cascade' }),
    website_quality_score: integer('website_quality_score'),
    classification: websiteClassification('classification').notNull(),
    category_scores: jsonb('category_scores').$type<CategoryScores>(),
    test_results: jsonb('test_results').$type<Record<string, unknown>>(),
    evidence: jsonb('evidence').$type<Record<string, unknown>>(),
    critical_failures: jsonb('critical_failures').$type<unknown[]>(),
    analysis_version: uuid('analysis_version').references(() => scoringVersions.id, { onDelete: 'restrict' }),
    analyzed_at: timestamp('analyzed_at', { withTimezone: true }),
    created_at: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (t) => [
    index('idx_website_analyses_website_id').on(t.website_id),
    index('idx_website_analyses_analyzed_at').on(t.analyzed_at),
    check('chk_website_analyses_score', sql`${t.website_quality_score} BETWEEN 0 AND 100 OR ${t.website_quality_score} IS NULL`),
  ],
);

