/* ============================================================================
 * 26. METRICS — daily aggregated operational metrics
 * ========================================================================== */

export const metrics = pgTable(
  'metrics',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    metric_date: date('metric_date').notNull(),
    metric_name: text('metric_name').notNull(),
    value: numeric('value', { precision: 14, scale: 2 }).notNull(),
    dimension: jsonb('dimension').$type<Record<string, string>>().notNull().default({}),
    // Deterministic canonical form of `dimension` — jsonb's text output is
    // key-normalized/canonical in Postgres, and a generated column is the
    // migration-tool-safe way to back the required unique constraint on
    // (metric_date, metric_name, dimension). sql`` is raw passthrough, so the
    // identifier `dimension` is resolved by the database against this table.
    dimension_key: text('dimension_key').generatedAlwaysAs(sql`(dimension)::text`),
    created_at: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (t) => [
    unique('u_metrics_date_name_dim').on(t.metric_date, t.metric_name, t.dimension_key),
  ],
);

